<script setup>
import {computed,onMounted,ref} from 'vue';
import {brewApi} from '../api';
const factories=ref([]),factory=ref(''),category=ref(''),keyword=ref(''),page=ref(1),items=ref([]),total=ref(0),units=ref([]),loading=ref(false),error=ref(''),selected=ref(null),detail=ref(null),detailLoading=ref(false),detailError=ref(''),detailTab=ref('lots');
const categories=[['','全部库存'],['malt','麦芽'],['adjunct','可发酵物 / 辅料'],['hop','啤酒花'],['yeast','酵母'],['packaging','包装材料'],['semi_finished','在制酒液'],['finished','成品酒'],['other','其他']];
const categoryName=c=>categories.find(x=>x[0]===c)?.[1]||'原料';
const number=(v)=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:3});
const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
const lotStatus=lot=>lot.frozen?'已冻结':lot.expiration_date&&lot.expiration_date<today?'已过期':quality[lot.quality_status]||lot.quality_status;
const quality={qualified:'合格',pending:'待检',quarantine:'待检',rejected:'不合格'};
const state={draft:'待执行',in_progress:'生产中',in_tank:'已进罐',completed:'已完成',cancelled:'已取消',released:'已放行',pending:'待包装'};
const date=v=>v?new Date(/[zZ]|[+-]\d\d:\d\d$/.test(v)?v:`${v}Z`).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}):'—';
const sourceName=value=>({'brew.production.plan':'生产计划','brew.material.requisition':'领料单','sale.order':'销售订单'}[value]||value);
const isBeer=computed(()=>['finished','semi_finished'].includes(detail.value?.product.category));
let loadId=0,detailId=0;
async function load(reset=false){if(reset)page.value=1;const id=++loadId;loading.value=true;error.value='';try{const data=await brewApi.browseStock({factory_id:factory.value,category:category.value,keyword:keyword.value,page:page.value,page_size:30});if(id!==loadId)return;items.value=data.items;total.value=data.total;units.value=data.units;factories.value=data.factories;}catch(e){if(id===loadId)error.value=e.message;}finally{if(id===loadId)loading.value=false;}}
async function open(row,historyPage=1,keepTab=false){const id=++detailId;selected.value=row;detailLoading.value=true;detailError.value='';if(historyPage===1&&!keepTab){detail.value=null;detailTab.value='lots';}try{const data=await brewApi.stockProduct(row.product.id,{factory_id:row.factory.id,history_page:historyPage});if(id===detailId)detail.value=data;}catch(e){if(id===detailId)detailError.value=e.message;}finally{if(id===detailId)detailLoading.value=false;}}
function close(){detailId++;selected.value=null;detail.value=null;}
onMounted(()=>load());
</script>
<template>
<section class="stock-browser">
<header class="stock-toolbar"><div class="stock-heading"><h3>酒厂库存</h3><p>查看库存余额、批次与生产来源</p></div><form class="stock-filters" @submit.prevent="load(true)"><label class="stock-factory-select"><span>酒厂</span><select v-model="factory" aria-label="选择酒厂" @change="load(true)"><option value="">全部授权酒厂</option><option v-for="f in factories" :key="f.id" :value="f.id">{{ f.name }}</option></select></label><input v-model.trim="keyword" aria-label="搜索库存" placeholder="物料名称、规格或批次"><button class="btn btn-sm btn-primary" type="submit">搜索</button><button class="btn btn-sm btn-outline" type="button" :disabled="loading" @click="load()">刷新</button></form></header>
<div class="stock-browser-layout"><aside class="stock-categories"><strong>库存分类</strong><button v-for="[key,label] in categories" :key="key" :class="{active:category===key}" @click="category=key;load(true)">{{ label }}</button></aside><main class="stock-content"><div class="stock-summary"><div><strong>{{ categoryName(category) }}</strong><span class="stock-count">{{ total }} 项</span></div><div class="stock-unit-balances"><span v-for="u in units" :key="u.unit">可用 <b>{{ number(u.available) }}</b> {{ u.unit }}</span></div></div><div v-if="error" class="master-error">{{ error }}</div><div v-if="loading" class="empty">正在加载库存…</div><div v-else class="work-table-wrap"><table class="work-table"><thead><tr><th>物料 / 规格</th><th>酒厂</th><th>账面库存</th><th>已占用</th><th>可用库存</th><th title="待检、冻结及过期库存">不可用</th><th>批次 / 有效期</th><th></th></tr></thead><tbody><tr v-for="row in items" :key="row.factory.id+':'+row.product.id"><td><strong>{{ row.product.name }}</strong><small>{{ row.product.beer_type||categoryName(row.product.category) }}<template v-if="row.product.specification"> · {{ row.product.specification }}</template></small></td><td>{{ row.factory.name }}</td><td>{{ number(row.on_hand) }} {{ row.product.unit }}</td><td>{{ number(row.reserved) }} {{ row.product.unit }}</td><td class="stock-available">{{ number(row.available) }} {{ row.product.unit }}</td><td>{{ number(row.blocked) }} {{ row.product.unit }}</td><td>{{ row.lot_count }} 批<small>{{ row.earliest_expiration||'无有效期' }}</small></td><td><button class="btn btn-xs btn-outline" @click="open(row)">查看详情</button></td></tr></tbody></table><div v-if="!items.length" class="empty">该酒厂及分类暂无库存。</div></div><footer class="stock-pagination"><button class="btn btn-xs btn-outline" :disabled="page<=1||loading" @click="page--;load()">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/30)) }}</span><button class="btn btn-xs btn-outline" :disabled="page*30>=total||loading" @click="page++;load()">下一页</button></footer></main></div>
<Teleport to="body"><div v-if="selected" class="equipment-modal-mask" @click.self="close"><section class="equipment-modal stock-detail" role="dialog" aria-modal="true" aria-label="库存详情"><header class="equipment-modal-header"><div><div class="modal-title">{{ selected.product.name }}</div><div class="modal-subtitle">{{ selected.factory.name }} · {{ selected.product.beer_type||categoryName(selected.product.category) }} · {{ selected.product.specification||selected.product.unit }}</div></div><button class="equipment-close" @click="close">×</button></header><div class="stock-detail-body"><div v-if="detailError" class="master-error">{{ detailError }}</div><div v-if="detailLoading&&!detail" class="empty">正在加载详情…</div><template v-if="detail"><div class="stock-detail-totals"><div v-for="[key,label] in [['on_hand','账面库存'],['reserved','已占用'],['available','可用库存'],['blocked','待检 / 冻结 / 过期']]" :key="key"><span>{{ label }}</span><strong>{{ number(detail[key]) }} <small>{{ detail.product.unit }}</small></strong></div></div><p class="stock-detail-note">供应商 {{ detail.product.supplier?.name||'见各入库批次' }}<span v-if="detail.product.code"> · 编码 {{ detail.product.code }}</span></p><nav class="stock-detail-tabs"><button v-for="[key,label] in [['lots','库存批次'],['locations','库位分布'],['reservations','库存占用'],['movements','出入库记录'],...(isBeer?[['production','生产历史']]:[])]" :key="key" class="btn btn-sm" :class="detailTab===key?'btn-primary':'btn-outline'" @click="detailTab=key">{{ label }}</button></nav>
<div v-if="detailTab==='lots'" class="work-table-wrap"><table class="work-table"><thead><tr><th>库存批次 / 来源</th><th>供应商 / 生产批次</th><th>数量</th><th>可用</th><th>状态</th><th>有效期</th><th>库位</th></tr></thead><tbody><tr v-for="lot in detail.lots" :key="lot.id"><td><strong>{{ lot.name }}</strong><small>{{ lot.supplier_lot||lot.packaging||'—' }}</small></td><td>{{ lot.source_batch||lot.supplier||'—' }}</td><td>{{ number(lot.on_hand) }} {{ lot.uom }}</td><td class="stock-available">{{ number(lot.available) }} {{ lot.uom }}</td><td>{{ lotStatus(lot) }}<small v-if="lot.frozen">冻结：{{ lot.freeze_reason }}</small></td><td>{{ lot.expiration_date||'—' }}</td><td>{{ lot.locations.map(l=>l.name).join('、') }}</td></tr></tbody></table><p v-if="!detail.lots.length" class="empty">没有批次信息，库存分布见库位页。</p></div>
<div v-if="detailTab==='locations'" class="work-table-wrap"><table class="work-table"><thead><tr><th>库位</th><th>账面</th><th>占用</th><th>可用</th></tr></thead><tbody><tr v-for="location in detail.locations" :key="location.id"><td>{{ location.name }}</td><td>{{ number(location.on_hand) }} {{ detail.product.unit }}</td><td>{{ number(location.reserved) }} {{ detail.product.unit }}</td><td>{{ number(location.available) }} {{ detail.product.unit }}</td></tr></tbody></table></div>
<div v-if="detailTab==='reservations'" class="work-table-wrap"><table class="work-table"><thead><tr><th>占用来源</th><th>数量</th><th>到期时间</th></tr></thead><tbody><tr v-for="r in detail.reservations" :key="r.id"><td>{{ sourceName(r.source) }} #{{ r.source_id }}</td><td>{{ number(r.quantity) }} {{ detail.product.unit }}</td><td>{{ date(r.expires_at) }}</td></tr></tbody></table><p v-if="!detail.reservations.length" class="empty">暂无业务预占记录。</p></div>
<div v-if="detailTab==='movements'" class="work-table-wrap"><p class="stock-detail-note">最近 50 条出入库记录</p><table class="work-table"><thead><tr><th>时间</th><th>单据</th><th>批次</th><th>数量</th><th>来源 → 去向</th></tr></thead><tbody><tr v-for="m in detail.movements" :key="m.id"><td>{{ date(m.date) }}</td><td>{{ m.source?.reference||'—' }}</td><td>{{ m.lot?.name||'—' }}</td><td>{{ number(m.quantity) }} {{ m.uom }}</td><td>{{ m.source_location||'—' }} → {{ m.destination_location||'—' }}</td></tr></tbody></table><p v-if="!detail.movements.length" class="empty">暂无出入库记录。</p></div>
<div v-if="detailTab==='production'" class="stock-history"><article v-for="batch in detail.production_history" :key="batch.id"><header><strong>{{ batch.name }}</strong><span>{{ state[batch.state]||batch.state }} · {{ date(batch.created_at) }}</span></header><p>{{ batch.plan }} · {{ batch.recipe }} · {{ batch.tank }} · 计划 {{ number(batch.planned_volume_l) }} L / 实际 {{ number(batch.actual_volume_l) }} L</p><div v-for="pack in batch.packaging" :key="pack.name">{{ pack.name }} · {{ pack.specification }} · 成品批次 {{ pack.lot||'未生成' }} · {{ number(pack.quantity) }} 件 / {{ number(pack.volume_l) }} L · {{ state[pack.state]||pack.state }}</div></article><p v-if="!detail.production_history.length" class="empty">暂无关联生产批次。</p><footer class="stock-pagination"><span>共 {{ detail.history_total }} 个生产批次</span><button class="btn btn-xs btn-outline" :disabled="detail.history_page<=1||detailLoading" @click="open(selected,detail.history_page-1,true)">上一页</button><button class="btn btn-xs btn-outline" :disabled="detail.history_page*20>=detail.history_total||detailLoading" @click="open(selected,detail.history_page+1,true)">下一页</button></footer></div>
</template></div><footer class="equipment-modal-footer"><button class="btn btn-secondary" @click="close">关闭</button></footer></section></div></Teleport>
</section>
</template>
<style scoped>
.stock-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:24px 0}.stock-toolbar>div{margin-right:auto}.stock-toolbar h3{margin:0 0 8px}.stock-toolbar p{color:#999;font-size:13px;margin:0}.stock-browser-layout{display:grid;grid-template-columns:175px minmax(0,1fr);gap:24px}.stock-categories{display:flex;flex-direction:column;gap:4px;border-right:1px solid #ffffff12;padding-right:16px}.stock-categories strong{color:#999;font-size:12px;padding:12px}.stock-categories button{background:none;border:0;text-align:left;padding:12px;color:#aaa;border-radius:8px;cursor:pointer}.stock-categories button.active{color:#d4a747;background:#d4a74712}.stock-summary{display:flex;flex-wrap:wrap;gap:16px;font-size:13px;color:#aaa;margin-bottom:16px}.work-table small{display:block;color:#999;margin-top:6px;font-size:12px}.stock-available{color:#c8b06e;font-weight:600}.stock-pagination{display:flex;justify-content:flex-end;gap:12px;align-items:center;margin-top:20px;font-size:13px;color:#aaa}.stock-detail{width:min(1120px,96vw);max-height:90vh;display:flex;flex-direction:column}.stock-detail-body{padding:24px;overflow:auto}.stock-detail-totals{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stock-detail-totals>div{padding:16px;background:#ffffff04;border-radius:8px}.stock-detail-totals span{display:block;color:#999;font-size:12px}.stock-detail-totals strong{display:block;margin-top:8px;font-size:23px}.stock-detail-totals small{font-size:12px}.stock-detail-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0 16px}.stock-detail-note{font-size:13px;color:#999}.stock-history article{border-bottom:1px solid #ffffff12;padding:18px 0}.stock-history header{display:flex;justify-content:space-between;gap:12px}.stock-history p,.stock-history article>div,.stock-history header span{font-size:13px;color:#aaa;margin:10px 0}@media(max-width:800px){.stock-browser-layout{grid-template-columns:1fr}.stock-categories{flex-direction:row;flex-wrap:wrap;border-right:0}.stock-categories strong{display:none}.stock-detail-totals{grid-template-columns:1fr 1fr}}

