und:#ffffff06;color:#aaa}.stock-unit-balances span{font-size:12px;color:#938f83}.stock-unit-balances b{color:#c4b17a;font-weight:600}.stock-content>.work-table-wrap .work-table th{background:rgba(255,255,255,.035);font-size:12px;padding:13px 16px}.stock-content>.work-table-wrap .work-table td{padding:16px;font-size:13px;border-color:#ffffff0c}.stock-content>.work-table-wrap .work-table tbody tr:hover{background:rgba(255,255,255,.025)}.stock-content>.work-table-wrap .work-table td strong{font-size:14px;font-weight:500}.stock-content>.work-table-wrap .work-table td:nth-child(n+3):nth-child(-n+6),.stock-content>.work-table-wrap .work-table th:nth-child(n+3):nth-child(-n+6){text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}.stock-content>.work-table-wrap .work-table td.stock-available{font-weight:600;color:#e1bd69}.stock-content>.stock-pagination{margin:0;padding:16px 18px;border-top:1px solid #ffffff12}.stock-detail-body input,.stock-detail-body select{background:#211f1a;color:#ded9ce}@media(max-width:1100px){.stock-toolbar{align-items:flex-start}.stock-filters{flex:1;justify-content:flex-end}.stock-filters input{width:210px}}@media(max-width:800px){.stock-browser-layout{grid-template-columns:1fr}.stock-categories{flex-direction:row;flex-wrap:wrap}.stock-filters{justify-content:flex-start}.stock-factory-select{flex:1}.stock-filters input{flex:1;min-width:180px}.stock-summary{align-items:flex-start;flex-direction:column}}
